\label{iso of covers}
Two covers $\mathcal{C}_f$ and $\mathcal{C}_g$ associated to $f,g\in \mathbb{F}_q(x)$ are isomorphic if there is an isomorphism $\varphi:\mathcal{C}_f\xrightarrow{\sim} \mathcal{C}_g$ defined over $\mathbb{F}_q$, which fits into a commuting diagram:
\[
\begin{tikzcd}
\mathcal{C}_f \arrow{r}{\varphi} \arrow[swap]{d}{} & \mathcal{C}_g \arrow{d}{} \\
\mathbf{P}^1  \arrow{r}{\operatorname{id}} & \mathbf{P}^1.
\end{tikzcd}
\]
We express this relation by simply writing $\mathcal{C}_f\simeq_{\mathbf{P}^1} \mathcal{C}_g$; note that it is stronger than requiring that $\mathcal{C}_f$ and $\mathcal{C}_g$ are isomorphic as curves.

\label{ul bounds}
Let $\kappa=(\kappa_1, \dots, \kappa_t)$ be a partition of $d+2$ as above such that $r+1=\sum_j \kappa_j$. Set $N(\kappa)$ to be the number of rational functions $h(x)/g(x)\in \mathbb{F}_q(x)$ such that
\begin{enumerate}
    \item $h(x)$ and $g(x)$ are coprime,
    \item $\operatorname{deg} h(x)\leq \operatorname{deg} g(x)$, 
    \item $g(x)=\prod_j g_j(x)^j$, where $g_j(x)$ is a monic squarefree polynomial of degree $\kappa_j$,
    \item for $i\neq j$, $g_i(x)$ and $g_j(x)$ are coprime.
\end{enumerate}
Then, we have that
\[\left(1-\frac{d+2-r}{q}\right)^{\lambda_1+1} q^{d+3}\leq N(\kappa)\leq \left(1-\frac{1}{q}\right)^{\lambda_2} q^{d+3},\]where $\lambda_i$ is the number of $\kappa_j$ that are $\geq i$, cf. \eqref{def of lambda}.

\label{lemma 3.1}
Let $\kappa\in \Omega_p(r+1, d+2)$. Let $\lambda_1$ and $\lambda_2$ be the quantities defined in the previous section, cf. \eqref{def of lambda}. We have the following assertions:
\begin{enumerate}
    \item\label{lemma 3.1 p1} Suppose that $\kappa_j=0$ for all $j\geq p$. Then, we have that 
\[ \left(1-\frac{d+2}{q}\right)^{\lambda_1+1}  q^{d+3}\leq \# \mathcal{S}_{g}^{\kappa}(\mathbb{F}_q)\leq \left(1-\frac{1}{q}\right)^{\lambda_2} q^{d+3},\] in particular, as $q\rightarrow \infty$,
\[\# \mathcal{S}_{g}^{\kappa}(\mathbb{F}_q)\sim  q^{d+3}.\]
\item Suppose that $\kappa_j\neq 0$ for some $j\geq p$. Then, we have that
\[\# \mathcal{S}_{g}^{\kappa}(\mathbb{F}_q)= o(q^{d+3}).\]
\end{enumerate}

\label{main}
Fix a prime number $p$ and let $r,d\geq 0$ such that $r\leq \lfloor d/2\rfloor$. Assume that $d$ is even when $p=2$. Set $g=d\left(\frac{p-1}{2}\right)$ and $\tau=r(p-1)$, and consider the limits $\mathfrak{d}'(p,g,\tau)$ (cf. \eqref{kappa}) and $\mathfrak{d}(p,g,\tau)$ (cf. \eqref{delta}). With respect to notation above, we have that 
\[\mathfrak{d}'(p,g,\tau)=\mathfrak{d}(p,g,\tau)=\frac{M_p(r+1, d+2)}{M_p(d+2)}.\]

\label{lemma 3.2}
Let $\kappa\in \Theta(r+1, d+2)$ and suppose that $\kappa_j=0$ for all $j\geq p$. Let $\lambda_1$ and $\lambda_2$ be the quantities defined in \eqref{def of lambda}. Then, we have that 
\[\left(1-\frac{d+2}{p}\right)^{\lambda_1+1}  p^{d+3}\leq \# \mathcal{S}_{g}^{\kappa}(\mathbb{F}_p)\leq \left(1-\frac{1}{p}\right)^{\lambda_2} p^{d+3}.\]

\label{last main theorem}
Fix a prime number $p$ and let $r,d\geq 0$ such that $r\leq \lfloor d/2\rfloor$. Recall that $\mathfrak{p}'(d,r)$ are $\mathfrak{p}(d,r)$ the limits defined by \eqref{def p prime} and \eqref{def p frak} respectively. Then, we have that
\[\mathfrak{p}(d, r)=\mathfrak{p}'(d, r)=\frac{T(r+1,d+2)}{T(d+2)}.\]
